// CharacterClassMutation represents an operation that mutates the CharacterClass nodes in the graph.
type CharacterClassMutation struct {
	config
	op               Op
	typ              string
	id               *int64
	class            *string
	subclass         *string
	level            *int
	addlevel         *int
	hit_dice         *string
	created_at       *string
	clearedFields    map[string]struct{}
	character        *int64
	clearedcharacter bool
	done             bool
	oldValue         func(context.Context) (*CharacterClass, error)
	predicates       []predicate.CharacterClass
}

var _ ent.Mutation = (*CharacterClassMutation)(nil)

// characterclassOption allows management of the mutation configuration using functional options.
type characterclassOption func(*CharacterClassMutation)

// newCharacterClassMutation creates new mutation for the CharacterClass entity.
func newCharacterClassMutation(c config, op Op, opts ...characterclassOption) *CharacterClassMutation {
	m := &CharacterClassMutation{
		config:        c,
		op:            op,
		typ:           TypeCharacterClass,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withCharacterClassID sets the ID field of the mutation.
func withCharacterClassID(id int64) characterclassOption {
	return func(m *CharacterClassMutation) {
		var (
			err   error
			once  sync.Once
			value *CharacterClass
		)
		m.oldValue = func(ctx context.Context) (*CharacterClass, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().CharacterClass.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withCharacterClass sets the old CharacterClass of the mutation.
func withCharacterClass(node *CharacterClass) characterclassOption {
	return func(m *CharacterClassMutation) {
		m.oldValue = func(context.Context) (*CharacterClass, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

// Client returns a new `ent.Client` from the mutation. If the mutation was
// executed in a transaction (ent.Tx), a transactional client is returned.
func (m CharacterClassMutation) Client() *Client {
	client := &Client{config: m.config}
	client.init()
	return client
}

// Tx returns an `ent.Tx` for mutations that were executed in transactions;
// it returns an error otherwise.
func (m CharacterClassMutation) Tx() (*Tx, error) {
	if _, ok := m.driver.(*txDriver); !ok {
		return nil, errors.New("ent: mutation is not running in a transaction")
	}
	tx := &Tx{config: m.config}
	tx.init()
	return tx, nil
}

