type NPCMutation struct {
	config
	op                    Op
	typ                   string
	id                    *int64
	name                  *string
	race                  *string
	class                 *string
	description           *string
	notes                 *string
	str                   *int
	addstr                *int
	dex                   *int
	adddex                *int
	con                   *int
	addcon                *int
	int                   *int
	addint                *int
	wis                   *int
	addwis                *int
	cha                   *int
	addcha                *int
	hp_max                *int
	addhp_max             *int
	hp_current            *int
	addhp_current         *int
	is_alive              *bool
	is_full               *bool
	ac                    *int
	addac                 *int
	speed                 *int
	addspeed              *int
	skills                *string
	saves                 *string
	features              *string
	actions               *string
	backstory             *string
	created_at            *string
	clearedFields         map[string]struct{}
	user                  *int64
	cleareduser           bool
	character_npcs        map[int64]struct{}
	removedcharacter_npcs map[int64]struct{}
	clearedcharacter_npcs bool
	done                  bool
	oldValue              func(context.Context) (*NPC, error)
	predicates            []predicate.NPC
}

var _ ent.Mutation = (*NPCMutation)(nil)

// npcOption allows management of the mutation configuration using functional options.
type npcOption func(*NPCMutation)

// newNPCMutation creates new mutation for the NPC entity.
func newNPCMutation(c config, op Op, opts ...npcOption) *NPCMutation {
	m := &NPCMutation{
		config:        c,
		op:            op,
		typ:           TypeNPC,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withNPCID sets the ID field of the mutation.
func withNPCID(id int64) npcOption {
	return func(m *NPCMutation) {
		var (
			err   error
			once  sync.Once
			value *NPC
		)
		m.oldValue = func(ctx context.Context) (*NPC, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().NPC.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withNPC sets the old NPC of the mutation.
func withNPC(node *NPC) npcOption {
	return func(m *NPCMutation) {
		m.oldValue = func(context.Context) (*NPC, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

// Client returns a new `ent.Client` from the mutation. If the mutation was
// executed in a transaction (ent.Tx), a transactional client is returned.
func (m NPCMutation) Client() *Client {
	client := &Client{config: m.config}
	client.init()
	return client
}

// Tx returns an `ent.Tx` for mutations that were executed in transactions;
// it returns an error otherwise.
func (m NPCMutation) Tx() (*Tx, error) {
	if _, ok := m.driver.(*txDriver); !ok {
		return nil, errors.New("ent: mutation is not running in a transaction")
	}
	tx := &Tx{config: m.config}
	tx.init()
	return tx, nil
}

